/* A scripted run through the editor's real DOM, for a browser to execute.
 *
 * bin/test cannot run this — there is no browser in it — so it is a file you
 * open: tests/editor-probe.html, generated by bin/build from editor/index.html
 * so it can never drift from the page it tests. Every assertion below is a bug
 * the editor once had. A green run means the writing loop still survives
 * adding, removing, clicking away mid-edit, folding, and deleting every line.
 *
 *   $ firefox tests/editor-probe.html      (or open it any other way) */
(function () {
  var out = [];
  function ok(name, cond, got) { out.push((cond ? 'ok   ' : 'FAIL ') + name + (cond ? '' : '  -> ' + got)); }
  function key(k, el, shift, ctrl) {
    (el || document).dispatchEvent(new KeyboardEvent('keydown',
      { key: k, shiftKey: !!shift, ctrlKey: !!ctrl, bubbles: true, cancelable: true }));
  }
  /* type a line into the command line and run it, the way : does */
  function run(text) {
    key(':');
    var input = document.getElementById('cmdInput');
    input.value = text;
    key('Enter', input);
  }
  /* put text in the command line and let it recompute its completions */
  function typeCmd(text) {
    key(':');
    var input = document.getElementById('cmdInput');
    input.value = text;
    input.dispatchEvent(new Event('input', { bubbles: true }));
    return input;
  }
  function msg()  { return document.getElementById('msg').textContent; }
  function name() { return document.getElementById('docname').textContent; }
  /* the tab bar shows the name only; the whole path is in the export overlay */
  function path() {
    run('export');
    var p = document.getElementById('expPath').textContent;
    key('Escape');
    return p;
  }
  function rows() {
    return [].map.call(document.querySelectorAll('#sheet .ln'), function (r) {
      return r.className.replace('ln ', '').replace(' cur', '*') + ':' +
             r.querySelector('.txt').textContent;
    });
  }
  function box() { return document.querySelector('#sheet .ln.cur .txt[contenteditable]'); }
  function type(text) {
    var b = box();
    if (!b) return false;
    b.textContent = text;
    return true;
  }

  /* start clean: one meta + one heading */
  var n0 = rows().length;

  /* --- the writing loop: o, type, Enter, type, Escape ------------------ */
  key('G');
  key('o');
  ok('o opens an edit box', !!box());
  type('first line');
  key('Enter', box());
  ok('Enter commits and opens the next box', !!box(), 'no box');
  type('second line');
  key('Escape', box());
  ok('Escape closes the box', !box());
  var r = rows();
  ok('both lines are in the document',
     r.join('|').indexOf('first line') > -1 && r.join('|').indexOf('second line') > -1, r.join('|'));
  ok('two lines were added', rows().length === n0 + 2, rows().length);

  /* --- remove, then keep editing --------------------------------------- */
  key('D');
  ok('D removed the line', rows().join('|').indexOf('second line') < 0, rows().join('|'));
  key('i');
  ok('i still opens a box after a removal', !!box());
  type('edited after removal');
  key('Escape', box());
  ok('the edit landed on the right line',
     rows().join('|').indexOf('edited after removal') > -1, rows().join('|'));

  /* --- clicking another line while the box is open --------------------- */
  key('i');
  type('mid-edit text');
  var target = document.querySelectorAll('#sheet .ln')[1];
  target.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
  target.dispatchEvent(new MouseEvent('click', { bubbles: true }));
  ok('a click while editing moves the cursor',
     document.querySelectorAll('#sheet .ln')[1].classList.contains('cur'),
     document.querySelector('#sheet .ln.cur').dataset.i);
  ok('and the text typed before the click was kept',
     rows().join('|').indexOf('mid-edit text') > -1, rows().join('|'));

  /* --- folded output: the cursor must never vanish into it ------------- */
  key('G');
  var before = rows().length;
  key('u');                        /* make the last line an output line */
  key('o');                        /* add another output line */
  ok('output lines can still be typed into', !!box());
  type('printed');
  key('Escape', box());
  key('z');                        /* fold this output run */
  key('z');                        /* and unfold it */
  key('i');
  ok('i works on a line whose run was just folded and unfolded', !!box());
  key('Escape', box());
  ok('the document did not lose lines to the fold', rows().length === before + 1, rows().length);

  /* --- delete every line ---------------------------------------------- */
  key('g');
  for (var i = 0; i < 60; i++) key('D');
  ok('deleting everything leaves exactly one line', rows().length === 1, rows().length);
  ok('and that line is an empty paragraph', /^p\*?:/.test(rows()[0]), rows()[0]);
  key('i');
  ok('the emptied document is still editable', !!box());
  type('back from empty');
  key('Escape', box());
  ok('and takes text', rows()[0].indexOf('back from empty') > -1, rows()[0]);

  /* --- undo and redo --------------------------------------------------- */
  var kept = rows().join('|');
  key('o');
  type('a line to take back');
  key('Escape', box());
  ok('the line is there to take back', rows().length === 2, rows().length);
  key('z', document, false, true);
  ok('^Z takes the change back', rows().join('|') === kept, rows().join('|'));
  key('z', document, true, true);
  ok('^⇧Z puts it back', rows().length === 2, rows().join('|'));
  key('z', document, false, true);
  ok('and ^Z takes it away again', rows().length === 1, rows().join('|'));
  key('j');
  key('k');
  key('z', document, false, true);
  ok('moving the cursor is not something to undo', rows().length === 1, rows().join('|'));

  /* --- the name of the file -------------------------------------------- */
  run('title Hello There');
  ok('the name follows the title while none is set', name() === 'hello-there.md', name());
  run('cat news');
  var p = path();
  ok('the category is the directory the file goes in', p === 'content/news/hello-there.md', p);
  run('name my-file.md');
  ok('a name that was set wins over the title', name() === 'my-file.md', name());
  run('title Something Else');
  ok('and goes on winning', name() === 'my-file.md', name());
  run('name');
  ok('an empty name follows the title again', name() === 'something-else.md', name());

  /* --- the command line ------------------------------------------------ */
  var n1 = rows().length;
  run('new p');
  ok(': new adds a line', rows().length === n1 + 1, rows().length);
  run('del');
  ok(': del takes it away', rows().length === n1, rows().length);
  run('set h2');
  ok(': set changes the type of the line',
     document.querySelector('#sheet .ln.cur').classList.contains('h2'),
     document.querySelector('#sheet .ln.cur').className);
  run('split');
  ok(': split shows both panes', document.getElementById('panes').dataset.mode === 'split');
  run('swap');
  ok(': swap swaps them, and stays in split',
     document.getElementById('panes').dataset.swap === 'yes' &&
     document.getElementById('panes').dataset.mode === 'split');
  run('swap');
  run('write');
  run('nonsense');
  ok('an unknown command is refused, not run', msg().indexOf('unknown command') === 0, msg());
  ok('every command in the table is documented in the help',
     document.querySelectorAll('#cmdlist .row').length >= 25,
     document.querySelectorAll('#cmdlist .row').length);

  /* --- new, clear, and getting them back ------------------------------- */
  document.getElementById('actNew').click();
  ok('New .md starts a document with its metadata and a heading',
     rows().length === 4, rows().join('|'));
  p = path();
  ok('and keeps the category it was filed under', p === 'content/news/untitled.md', p);
  ok('and goes back to being called untitled', name() === 'untitled.md', name());
  document.getElementById('actClear').click();
  ok('Clear leaves one empty line', rows().length === 1, rows().join('|'));
  key('z', document, false, true);
  ok('and ^Z brings the whole document back', rows().length === 4, rows().join('|'));

  /* --- Tab completes arguments, and leaves alone what it cannot complete -- */
  var input = typeCmd('title My Great Post');
  key('Tab', input);
  ok('Tab leaves an argument it has no completions for',
     input.value === 'title My Great Post', input.value);
  key('Escape', input);

  input = typeCmd('set code p');
  key('Tab', input);
  ok('Tab completes a dialect for the second argument of set',
     input.value === 'set code php ', input.value);
  key('Escape', input);

  input = typeCmd('se');
  key('Tab', input);
  ok('and completes a command name for the first word', input.value === 'set ', input.value);
  key('Escape', input);

  /* --- folding is looking, not editing ---------------------------------- */
  key('G');
  key('u');                        /* the last line becomes output */
  key('o');
  type('printed');
  key('Escape', box());
  var withPrinted = rows().length;
  key('z');                        /* fold the run */
  key('z');                        /* and unfold it — the same view again */
  key('z', document, false, true);
  ok('folding is not a step to undo — ^Z takes back the text instead',
     rows().length === withPrinted - 1, rows().length + ' of ' + withPrinted);

  /* --- tables: a row the width of its Run, and Tab between its Cells ---- */
  function cellsIn(b) { return window.TerminalCms.cells(b.textContent); }
  /* the caret in the open box, counted in characters, read and written */
  function caret() {
    var b = box(), s = getSelection(), r = document.createRange();
    if (!b || !s.rangeCount) return -1;
    r.selectNodeContents(b);
    r.setEnd(s.getRangeAt(0).endContainer, s.getRangeAt(0).endOffset);
    return r.toString().length;
  }
  function putCaret(at) {
    var b = box(), r = document.createRange();
    if (b.firstChild) r.setStart(b.firstChild, at); else r.selectNodeContents(b);
    r.collapse(true);
    var s = getSelection();
    s.removeAllRanges();
    s.addRange(r);
  }

  document.getElementById('actClear').click();
  key('t');                          /* the one line becomes a Table Line */
  key('i');
  type('one | two | three');
  key('Escape', box());
  key('o');
  ok('o on a Line of a three-Column Run opens a three-Cell row',
     !!box() && cellsIn(box()).length === 3, box() && box().textContent);

  type('a | b | c');
  putCaret(0);
  key('Tab', box());
  ok('Tab moves the caret to the next Cell',
     caret() === box().textContent.indexOf('b') + 1, caret());
  key('Tab', box());
  ok('and on to the Cell after that',
     caret() === box().textContent.indexOf('c') + 1, caret());
  var nt = rows().length;
  key('Tab', box());
  ok('Tab on the last Cell opens the next row', rows().length === nt + 1, rows().length);
  ok('with the caret in its first Cell', !!box() && caret() === 0, caret());
  ok('and that row is the width of the Run too',
     cellsIn(box()).length === 3, box().textContent);
  ok('the row Tab left behind was committed',
     rows().join('|').indexOf('a | b | c') > -1, rows().join('|'));
  key('Tab', box(), true);
  ok('Shift-Tab on the first Cell does nothing',
     !!box() && caret() === 0 && rows().length === nt + 1, caret() + ' of ' + rows().length);
  key('Escape', box());

  document.getElementById('actClear').click();
  key('t');
  key('i');
  type('x | y');
  key('Enter', box());
  ok('Enter while editing a Table Line still commits and opens the next Line',
     !!box() && rows().join('|').indexOf('x | y') > -1, rows().join('|'));
  key('Escape', box());

  /* the bug the probe first missed: Tab out of the very first row of a table,
     whose text was still only in the box when the next row was sized */
  document.getElementById('actClear').click();
  key('t');
  key('i');
  type('p | q | r');
  putCaret(box().textContent.length);
  key('Tab', box());
  ok('Tab out of the first row of a new table commits it before measuring it',
     !!box() && cellsIn(box()).length === 3, box() && box().textContent);
  ok('and the row it came from is in the document',
     rows().join('|').indexOf('p | q | r') > -1, rows().join('|'));
  key('Escape', box());

  /* --- columns: one command, every Line of the Run ---------------------- */
  function tableRows() {
    return rows().filter(function (r) { return r.indexOf('table') === 0; })
                 .map(function (r) { return r.slice(r.indexOf(':') + 1); });
  }
  function compls() {
    return [].map.call(document.querySelectorAll('#compl b'), function (b) {
      return b.textContent;
    });
  }

  document.getElementById('actClear').click();
  key('t');
  key('i');
  type('one | two | three');
  key('Escape', box());
  key('o');
  type('a | b | c');
  key('Escape', box());
  var before = tableRows().join(' / ');
  ok('the table the column commands work on is two rows of three',
     before === 'one | two | three / a | b | c', before);

  run('col add');
  ok(':col add puts an empty Column on the right of every Line',
     tableRows().join(' / ') === 'one | two | three |  / a | b | c | ',
     tableRows().join(' / '));
  key('z', document, false, true);
  ok('and one :col is one ^Z', tableRows().join(' / ') === before, tableRows().join(' / '));

  run('col del 2');
  ok(':col del takes that Column out of every Line',
     tableRows().join(' / ') === 'one | three / a | c', tableRows().join(' / '));

  run('col left 2');
  ok(':col left swaps it with the Column before it, in every Line',
     tableRows().join(' / ') === 'three | one / c | a', tableRows().join(' / '));

  run('col del 99');
  ok(':col del on a Column the table has not got is refused',
     msg().indexOf('no column 99') === 0, msg());
  ok('and the table is exactly as it was',
     tableRows().join(' / ') === 'three | one / c | a', tableRows().join(' / '));

  input = typeCmd('col del ');
  ok('Tab completion on :col del offers the headings against their numbers',
     compls().join(',') === '1 three,2 one', compls().join(','));
  key('Tab', input);
  ok('and picking one writes its number into the command',
     input.value.indexOf('col del 1 three') === 0, input.value);
  key('Escape', input);

  /* --- the strip: a Table that says what its Columns are ---------------- */
  /* one entry per Column, each its number and its heading Cell, and a `*` on
     the one that is selected */
  function strip() {
    return [].map.call(document.querySelectorAll('#sheet .colstrip b'), function (b) {
      return b.textContent + (b.classList.contains('on') ? '*' : '');
    }).join(' / ');
  }
  /* the drawn Cells of the nth Table row on the sheet */
  function cellsOf(n) {
    var r = document.querySelectorAll('#sheet .ln.table')[n];
    return r ? r.querySelectorAll('.cell') : [];
  }

  document.getElementById('actClear').click();
  key('t');
  key('i');
  type('one | two | three');
  key('Escape', box());
  key('o');
  type('a | b | c');
  key('Escape', box());
  ok('a Table Run draws one strip entry per Column, carrying the heading row',
     strip() === '1one / 2two / 3three', strip());

  document.getElementById('actClear').click();
  key('t');
  key('i');
  type('one | two');
  key('Escape', box());
  key('o');
  type('a | b | c');
  key('Escape', box());
  ok('a ragged Run draws the entries its widest row asks for',
     strip() === '1one / 2two / 3', strip());
  ok('and drawing the strip changed no Line',
     tableRows().join(' / ') === 'one | two / a | b | c', tableRows().join(' / '));

  document.getElementById('actClear').click();
  ok('a document with no Table draws no strip', strip() === '', strip());

  /* two Runs, a Paragraph between them, so the bounds have something to stop at */
  document.getElementById('actClear').click();
  key('t');
  key('i');
  type('a1 | a2');
  key('Escape', box());
  key('o');
  key('Escape', box());
  key('p');
  key('i');
  type('between');
  key('Escape', box());
  key('o');
  key('Escape', box());
  key('t');
  key('i');
  type('b1 | b2 | b3');
  key('Escape', box());
  ok('with two Tables the strip is the Run the cursor is in',
     strip() === '1b1 / 2b2 / 3b3', strip());
  key('k');
  ok('a cursor out of the Run draws no strip', strip() === '', strip());
  key('k');
  ok('and in the Run above, the strip is that Run and its Column count',
     strip() === '1a1 / 2a2', strip());

  document.querySelectorAll('#sheet .colstrip b')[1].click();
  ok('clicking an entry selects that Column, visibly',
     strip() === '1a1 / 2a2*', strip());
  key('j');
  ok('the cursor leaving the Run clears the selection with the strip',
     strip() === '', strip());
  key('k');
  ok('and coming back in, nothing is selected', strip() === '1a1 / 2a2', strip());

  document.querySelectorAll('#sheet .colstrip b')[1].click();
  key('G');
  ok('the selection does not travel to the other Run',
     strip() === '1b1 / 2b2 / 3b3', strip());

  /* the selection is the Run's, not the Line's: walking the Run keeps it, and
     it is anchored on a Line object, so an edit above cannot re-point it */
  document.getElementById('actClear').click();
  key('t');
  key('i');
  type('one | two | three');
  key('Escape', box());
  key('o');
  type('a | b | c');
  key('Escape', box());
  document.querySelectorAll('#sheet .colstrip b')[2].click();
  key('k');
  ok('moving within the Run keeps the Column selected',
     strip() === '1one / 2two / 3three*', strip());
  run('col del 3');
  ok('and a Column that is no longer there is no longer selected',
     strip() === '1one / 2two', strip());

  /* --- a Cell is a place to click: the row, and the caret inside it ----- */
  document.getElementById('actClear').click();
  key('t');
  key('i');
  type('a | b | c');
  key('Escape', box());
  ok('a Table row draws one span per Cell', cellsOf(0).length === 3, cellsOf(0).length);

  cellsOf(0)[0].click();
  ok('clicking the first Cell opens the row with the caret in that Cell',
     !!box() && caret() === 1, caret());
  key('Escape', box());
  cellsOf(0)[2].click();
  ok('and clicking the last Cell lands in the last Cell',
     !!box() && caret() === 9, caret());
  key('Escape', box());

  key('o');
  type('d | e | f');
  key('Escape', box());
  cellsOf(0)[1].click();
  ok('clicking a Cell of another row puts the cursor on that row',
     !!box() && box().textContent === 'a | b | c', box() && box().textContent);
  ok('with the caret in the Cell that was clicked', caret() === 5, caret());
  key('Escape', box());
  ok('and the rows are as they were typed',
     tableRows().join(' / ') === 'a | b | c / d | e | f', tableRows().join(' / '));

  /* a tap is a click with a finger behind it: a Cell names a place, so one tap
     is the way in, where a Line still takes the second */
  document.dispatchEvent(new PointerEvent('pointerdown',
    { pointerType: 'touch', bubbles: true }));
  cellsOf(1)[0].click();
  ok('a tap on a Cell opens it the same way a click does',
     !!box() && box().textContent === 'd | e | f' && caret() === 1,
     (box() && box().textContent) + ' @ ' + caret());
  key('Escape', box());
  document.dispatchEvent(new PointerEvent('pointerdown',
    { pointerType: 'mouse', bubbles: true }));

  document.querySelectorAll('#sheet .colstrip b')[0].click();
  var readTbl = document.querySelector('#read table');
  ok('the read pane still renders the Table, and nothing of the strip',
     !!readTbl && readTbl.textContent.replace(/\s+/g, '') === 'abcdef' &&
     document.querySelectorAll('#read .colstrip, #read .cell').length === 0,
     (readTbl && readTbl.textContent.replace(/\s+/g, '')) + ' :: ' +
     document.querySelectorAll('#read .colstrip, #read .cell').length);
  run('export');
  var stripMd = document.getElementById('expMd').textContent;
  key('Escape');
  ok('and export is the table it always was',
     stripMd.indexOf('| a | b | c |\n| --- | --- | --- |\n| d | e | f |') > -1 &&
     stripMd.indexOf('colstrip') < 0, stripMd);

  document.getElementById('actClear').click();
  key('c');
  key('Tab');
  ok('Tab outside the box still cycles the Dialect',
     msg() === 'js' && document.querySelector('#sheet .run.code .lang').textContent === 'js',
     msg() + ' :: ' + document.querySelector('#sheet .run.code .lang').textContent);

  /* --- the address overlay: the links in a line, and an image's two halves -- */
  function addrOn()  { return document.getElementById('addr').classList.contains('on'); }
  function picking() { return addrOn() && !document.getElementById('addrPick').hidden; }
  function fa()      { return document.getElementById('addrA'); }
  function fb()      { return document.getElementById('addrB'); }
  function warn()    { return document.getElementById('addrWarn').textContent; }
  /* a fresh document holding one line of the given text */
  function oneLine(text) {
    document.getElementById('actClear').click();
    key('i');
    type(text);
    key('Escape', box());
  }

  oneLine('see [one](https://a.example/) and [two](https://b.example/)');
  key('a');
  ok('a on a line with two links opens the picker', picking());
  ok('the picker offers both links and a new one',
     document.querySelectorAll('#addrPick b').length === 3,
     document.querySelectorAll('#addrPick b').length);
  key('2');
  ok('picking the second fills the form with the second link',
     fa().value === 'two' && fb().value === 'https://b.example/',
     fa().value + ' / ' + fb().value);
  key('Escape', fa());
  key('a');
  key('j');
  key('Enter');
  ok('j and Enter reach the same link the digit does',
     !picking() && fa().value === 'two' && fb().value === 'https://b.example/',
     fa().value + ' / ' + fb().value);
  key('Escape', fa());
  key('a');
  key('j');
  key('k');
  key('Enter');
  ok('k comes back up the list', fa().value === 'one', fa().value);
  key('Escape', fa());
  key('a');
  key('2');
  fa().focus();
  key('Tab', fa());
  ok('Tab moves to the other field', document.activeElement === fb(),
     document.activeElement && document.activeElement.id);
  fa().value = 'TWO';
  fb().value = 'https://c.example/';
  key('Enter', fb());
  ok('Enter commits and closes the overlay', !addrOn());
  ok('and the line carries the link that was typed',
     rows().join('|').indexOf('see [one](https://a.example/) and [TWO](https://c.example/)') > -1,
     rows().join('|'));

  var kept2 = rows().join('|');
  key('a');
  key('1');
  fa().value = 'thrown away';
  key('Escape', fa());
  ok('Esc leaves the line exactly as it was',
     !addrOn() && rows().join('|') === kept2, rows().join('|'));

  run('link');
  ok(': link opens the same overlay as a', addrOn());
  key('Escape', fa());
  run('img');
  ok(': img opens it too', addrOn());
  key('Escape', fa());

  oneLine('one [only](https://a.example/) here');
  key('a');
  ok('one link goes straight to a filled form',
     addrOn() && !picking() && fa().value === 'only', fa().value);
  key('Escape', fa());

  oneLine('no links here');
  key('a');
  ok('no links goes straight to an empty form',
     addrOn() && !picking() && !fa().value && !fb().value, fa().value + ' / ' + fb().value);
  fa().value = 'fresh';
  fb().value = 'https://d.example/';
  key('Enter', fa());
  ok('a new link is appended to the line',
     rows().join('|').indexOf('no links here [fresh](https://d.example/)') > -1, rows().join('|'));

  key('a');
  fb().value = '';
  key('Enter', fa());
  ok('an empty href unlinks and keeps the wording',
     rows().join('|').indexOf('no links here fresh') > -1 &&
     rows().join('|').indexOf('[fresh]') < 0, rows().join('|'));

  oneLine('a [word](https://a.example/) here');
  var before2 = rows().join('|');
  key('a');
  fa().value = '';
  key('Enter', fa());
  ok('an empty wording is refused, with a message and no change',
     addrOn() && msg().indexOf('wording') > -1 && rows().join('|') === before2,
     msg() + ' :: ' + rows().join('|'));

  fa().value = 'word';
  fb().value = 'javascript:alert';
  fb().dispatchEvent(new Event('input', { bubbles: true }));
  ok('an href the allowlist refuses is marked in the overlay',
     warn().indexOf('print as text') > -1, warn());
  key('Enter', fb());
  ok('and Enter commits it anyway',
     !addrOn() && rows().join('|').indexOf('[word](javascript:alert)') > -1, rows().join('|'));

  key('z', document, false, true);
  ok('one committed overlay is one ^Z',
     rows().join('|') === before2, rows().join('|'));

  document.getElementById('actClear').click();
  key('c');
  var kept3 = rows().join('|');
  key('a');
  ok('a on a code line says so and changes nothing',
     !addrOn() && msg().indexOf('nothing to address') > -1 && rows().join('|') === kept3,
     msg() + ' :: ' + rows().join('|'));

  /* the legend is the whole interface where there is no keyboard, so the
     address overlay has to be reachable from it and not from `a` alone */
  oneLine('[wording](https://a.example/)');
  var addrChip = document.querySelector('#legend b[data-a="addr"]');
  ok('the legend offers the address action', !!addrChip,
     document.querySelectorAll('#legend b[data-a]').length + ' actions');
  ok('and prints the key that does the same thing',
     !!addrChip && addrChip.querySelector('i').textContent === 'a',
     addrChip && addrChip.innerHTML);
  if (addrChip) { addrChip.click(); }
  ok('clicking it opens the overlay on the line under the cursor',
     addrOn() && !picking() && fa().value === 'wording', fa().value);
  key('Escape');

  document.getElementById('actClear').click();
  key('f');
  key('a');
  ok('a on an image line offers src and caption',
     addrOn() && document.getElementById('addrLab1').textContent === 'src' &&
     document.getElementById('addrLab2').textContent === 'caption',
     document.getElementById('addrLab1').textContent);
  fa().value = 'diagram.png';
  fb().value = 'how it fits together';
  key('Enter', fb());
  run('export');
  var md = document.getElementById('expMd').textContent;
  key('Escape');
  ok('a committed caption reaches the export',
     md.indexOf('![how it fits together](diagram.png)') > -1, md);
  var fig = document.querySelector('#read figure');
  ok('and the read pane shows the picture itself',
     !!document.querySelector('#read figure img[src="diagram.png"]'),
     fig && fig.innerHTML);
  ok('with the box holding the file name behind it, for an src that will not load',
     !!fig && !!fig.querySelector('.imgbox[hidden]') &&
     fig.querySelector('.imgbox').textContent === 'diagram.png',
     fig && fig.innerHTML);
  ok('and the caption is the alt as well as the figcaption',
     !!fig && fig.querySelector('img').alt === 'how it fits together' &&
     fig.querySelector('figcaption').textContent === 'how it fits together',
     fig && fig.innerHTML);

  oneLine('[kept  wording](https://a.example/)');
  key('a');
  fb().value = '';
  key('Enter', fa());
  ok('unlinking keeps the wording the field shows',
     rows().join('|').indexOf('kept  wording') > -1 &&
     rows().join('|').indexOf('[') < 0, rows().join('|'));

  oneLine('[old](https://a.example/)');
  key('a');
  fa().value = 'new wording';
  fb().value = '';
  key('Enter', fa());
  ok('and a wording edited on the way out is not thrown away',
     rows().join('|').indexOf('new wording') > -1, rows().join('|'));

  /* --- ^K: the link lands where the writer is ---------------------------- */
  /* The overlay reached from inside the box, with the offsets read off the box
     itself. `a` on a closed Line still appends — there is no caret in it. */
  function putSelection(at, end) {
    var b = box(), r = document.createRange(), s = getSelection();
    r.setStart(b.firstChild, at);
    r.setEnd(b.firstChild, end);
    s.removeAllRanges();
    s.addRange(r);
  }
  function ctrlK() { key('k', box(), false, true); }

  oneLine('take these words away');
  key('i');
  putSelection(5, 16);
  ctrlK();
  ok('^K with a selection opens the overlay with the selection as the wording',
     addrOn() && !picking() && fa().value === 'these words', fa().value);
  fb().value = 'https://w.example/';
  key('Enter', fb());
  var placed = rows().join('|');
  ok('committing replaces exactly the selected span, and the rest is untouched',
     placed.indexOf('take [these words](https://w.example/) away') > -1, placed);
  ok('the caret sits after the inserted link', caret() === 38, caret());
  document.execCommand('insertText', false, '!');
  ok('and typing carries on there',
     box() && box().textContent.indexOf(')! away') > -1, box() && box().textContent);
  key('Escape', box());

  oneLine('before after');
  key('i');
  putCaret(7);
  ctrlK();
  ok('^K with a caret and no selection opens an empty form',
     addrOn() && !picking() && !fa().value && !fb().value, fa().value + ' / ' + fb().value);
  fa().value = 'here';
  fb().value = 'https://h.example/';
  key('Enter', fb());
  ok('and the committed link lands at the caret',
     rows().join('|').indexOf('before [here](https://h.example/)after') > -1, rows().join('|'));
  key('Escape', box());
  key('z', document, false, true);
  ok('one insertion at the caret is one ^Z',
     rows().join('|').indexOf('before after') > -1 &&
     rows().join('|').indexOf('[here]') < 0, rows().join('|'));

  oneLine('leave me alone');
  var keptK = rows().join('|');
  key('i');
  putCaret(5);
  ctrlK();
  fa().value = 'never';
  fb().value = 'https://n.example/';
  key('Escape', fb());
  key('Escape', box());
  ok('Esc leaves the line exactly as it was',
     !addrOn() && rows().join('|') === keptK, rows().join('|'));

  oneLine('take these words away');
  key('i');
  putSelection(4, 16);
  ctrlK();
  ok('a selection that took a space with it links the phrase, not the space',
     fa().value === 'these words', fa().value);
  fb().value = 'https://w.example/';
  key('Enter', fb());
  ok('and the space it took is still there',
     rows().join('|').indexOf('take [these words](https://w.example/) away') > -1,
     rows().join('|'));
  key('Escape', box());
  key('z', document, false, true);
  ok('one link over a selection is one ^Z too',
     rows().join('|').indexOf('take these words away') > -1, rows().join('|'));

  oneLine('keep this exactly');
  key('i');
  putSelection(5, 9);
  ctrlK();
  key('Escape', fa());
  ok('Esc hands the selection back, not just the text',
     !addrOn() && !!box() && String(getSelection()) === 'this', String(getSelection()));
  key('Escape', box());

  document.getElementById('actClear').click();
  key('f');
  key('i');
  var keptF = rows().join('|');
  ctrlK();
  ok('^K on an image line offers nothing new and changes nothing',
     !addrOn() && msg().indexOf('src and caption') > -1 && rows().join('|') === keptF,
     msg() + ' :: ' + rows().join('|'));
  key('Escape', box());

  oneLine('see [one](https://a.example/) here');
  key('i');
  putCaret(29);
  ctrlK();
  fa().value = 'two';
  fb().value = 'https://b.example/';
  key('Enter', fb());
  key('Escape', box());
  ok('a line that already carried a link reports both afterwards, in order',
     window.TerminalCms.links(rows().join('|')).map(function (k) { return k.wording; })
       .join(' ') === 'one two',
     rows().join('|'));

  oneLine('tail text');
  key('a');
  fa().value = 'end';
  fb().value = 'https://e.example/';
  key('Enter', fb());
  ok('a on a line that is not being edited still appends',
     rows().join('|').indexOf('tail text [end](https://e.example/)') > -1, rows().join('|'));

  document.getElementById('actClear').click();
  key('c');
  key('i');
  var keptC = rows().join('|');
  ctrlK();
  ok('^K on a code line says so and changes nothing',
     !addrOn() && msg().indexOf('nothing to address') > -1 && rows().join('|') === keptC,
     msg() + ' :: ' + rows().join('|'));
  key('Escape', box());

  document.getElementById('actClear').click();
  key('t');
  key('i');
  type('a | b | c');
  putCaret(1);
  key('Tab', box());
  ok('Tab still walks Cells, unaffected by the new binding', caret() === 5, caret());
  key('Escape', box());

  var bad = out.filter(function (l) { return l.indexOf('FAIL') === 0; }).length;
  var pre = document.createElement('pre');
  pre.style.cssText = 'position:fixed;inset:0;z-index:999;background:#111;color:#ddd;' +
    'font:12px/1.5 monospace;padding:14px;margin:0;overflow:auto;white-space:pre-wrap';
  pre.textContent = out.join('\n') + '\n\n' + bad + ' failed of ' + out.length;
  document.body.appendChild(pre);
})();
